"""Offline, source-bound review for exact incremental scientific archives."""
from __future__ import annotations
import html
import json
import shlex


def render(data):
    m = data['manifest']
    base = shlex.quote(m['base']['filename'])
    delta = shlex.quote(data['delta_filename'])
    command = ('python source_tools/archive_delta.py restore ' + base + ' ' + delta
               + ' received-edition.zip NEW_RECEIVING_DIRECTORY --application ORIGINAL_APPLICATION')
    payload = json.dumps(data, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
    template = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Incremental study delivery</title><style>
*{box-sizing:border-box}body{margin:0;background:#ececec;color:#202020;font:15px/1.5 system-ui,sans-serif}main{max-width:1220px;margin:auto;padding:32px 28px 60px}header{border-bottom:2px solid #292929;padding-bottom:24px}h1{font-size:32px;font-weight:600;letter-spacing:-.03em;line-height:1.15;margin:12px 0}h2{font-size:19px;margin:0 0 14px}p{margin:8px 0}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-size:11px;font-weight:650}.muted{color:#555}section{background:#fafafa;border:1px solid #c8c8c8;padding:22px;margin-top:22px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:24px}.stat{background:#f8f8f8;border:1px solid #c8c8c8;padding:20px}.stat strong{display:block;font-size:30px;line-height:1.2;margin:6px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.label{font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:#555}.filename{font-weight:600;overflow-wrap:anywhere}.identity{font:12px/1.65 ui-monospace,monospace;overflow-wrap:anywhere;margin-top:8px}.badge{display:inline-block;padding:3px 8px;border:1px solid #888;background:#eee;font-size:12px}.toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:12px}label{display:flex;flex-direction:column;gap:5px;flex:1;min-width:150px;font-size:13px}input,select,button{font:inherit;color:inherit;background:#fff;border:1px solid #888;border-radius:0;min-height:40px;padding:9px 12px}button{cursor:pointer}button:hover{background:#e6e6e6}button:disabled{opacity:.45;cursor:default}input:focus-visible,select:focus-visible,button:focus-visible{outline:2px solid #111;outline-offset:2px}button.primary{background:#292929;color:#fff;border-color:#292929}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin-top:18px;font-size:13px}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid #ddd;vertical-align:top;overflow-wrap:anywhere}th{font-size:11px;text-transform:uppercase;letter-spacing:.06em;border-bottom:1px solid #888}th:nth-child(1){width:13%}th:nth-child(2){width:59%}th:nth-child(3),th:nth-child(4){width:14%;text-align:right}td:nth-child(3),td:nth-child(4){text-align:right;font-variant-numeric:tabular-nums}.path{font:12px/1.6 ui-monospace,monospace}.pagination{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;margin-top:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:16px;background:#ececec;border:1px solid #ccc;font:12px/1.7 ui-monospace,monospace}details summary{cursor:pointer;font-weight:600}footer{margin-top:24px;font-size:12px;color:#555}#empty{padding:28px 0}.notice{border-left:3px solid #333;padding-left:14px}.screen-reader{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:700px){main{padding:20px 14px 36px}h1{font-size:27px}.stats{grid-template-columns:1fr;gap:8px}.stat{padding:14px 16px;display:grid;grid-template-columns:1fr 1fr}.stat strong{font-size:25px;margin:0;text-align:right}.stat .muted{grid-column:1/-1}.grid{grid-template-columns:1fr;gap:18px}section{padding:17px 14px}.toolbar{gap:8px}label{min-width:100%}th,td{padding:10px 5px}th:nth-child(1){width:20%}th:nth-child(2){width:44%}th:nth-child(3),th:nth-child(4){width:18%}th{font-size:10px;letter-spacing:0}.path{font-size:11px}.pagination button{padding:9px}.identity{font-size:11px}}
</style><main><header><div class="eyebrow">Ecosystem Sciences / editable study receiving</div><h1>Send the changes.<br>Keep the complete study.</h1><p id="title" class="filename"></p><p class="muted">This package reconstructs the producer’s exact full native archive from the retained base and changed ZIP records. Original sources, completed model outputs and editable history stay in the resulting study.</p></header>
<div class="stats"><div class="stat"><span class="label">Transfer this edition</span><strong id="delta-size"></strong><span class="muted" id="saved"></span></div><div class="stat"><span class="label">Complete result</span><strong id="target-size"></strong><span class="muted" id="member-count"></span></div><div class="stat"><span class="label">Reuse locally</span><strong id="reuse-size"></strong><span class="muted">Unchanged compressed archive records</span></div></div>
<section><h2>Two files in, one original archive out</h2><div class="grid"><div><div class="label">Already retained / required base</div><p id="base-name" class="filename"></p><div id="base-hash" class="identity"></div></div><div><div class="label">Send / incremental package</div><p id="delta-name" class="filename"></p><div id="delta-hash" class="identity"></div></div></div><p class="notice muted" style="margin-top:20px">The base must match exactly. Keep earlier archives and recipient edits. A delta is a transport package, not a standalone study; the reconstructed ZIP opens through the original application.</p><div class="actions"><button id="manifest">Download complete delivery recipe</button><button id="csv">Download all file changes</button></div></section>
<section><h2>Original file changes</h2><div class="toolbar"><label>Find an original path<input id="filter" type="search" placeholder="Scenario, report, source or application path"></label><label style="flex:0 1 260px">Show<select id="status"><option value="different">Added, changed and removed</option><option value="all">All original members</option><option value="added">Added</option><option value="changed">Changed</option><option value="removed">Removed</option><option value="unchanged">Unchanged</option></select></label><button id="clear">Clear</button></div><p id="count" class="muted" aria-live="polite"></p><table><thead><tr><th>Status</th><th>Original path</th><th>Before</th><th>After</th></tr></thead><tbody id="rows"></tbody></table><p id="empty" hidden>No original paths match this selection.</p><div class="pagination"><span id="page" class="muted"></span><div><button id="prev">Previous</button> <button id="next">Next</button></div></div></section>
<section><h2>Receive and continue editing</h2><p>Place the base archive and incremental package together. Run the supplied receiver from the retained application source. Replace the two directory placeholders with your original application and a new receiving directory.</p><pre id="command">COMMAND</pre><p class="muted">A stopped transfer resumes from its verified journal using the same command and output path. The final SHA-256 is checked before publication. Native receiving then verifies its complete original inventory and opens an independent editable project.</p><div class="actions"><button class="primary" id="instructions">Download receiving instructions</button></div><details style="margin-top:22px"><summary>Exact reconstructed edition</summary><p class="filename" id="target-name"></p><div class="identity" id="target-hash"></div><p class="muted">The transport does not merge edits into an existing Workspace or run a scientific model. Continue through the original scenario, report, native-run and saved-study controls after receiving.</p><div class="identity" id="recipe-id"></div></details></section><footer>Version 1.0.0 · Offline reader · Bytes shown are measured archive sizes. The original scientific scope and interpretation remain in the retained study.</footer></main>
<script id="delivery" type="application/json">PAYLOAD</script><script>
'use strict';const D=JSON.parse(document.getElementById('delivery').textContent),M=D.manifest;const $=id=>document.getElementById(id);function size(n){if(n==null)return '—';if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KiB';return(n/1048576).toFixed(2)+' MiB'}function text(id,v){$(id).textContent=v}text('title',M.target.project.title);text('delta-size',size(D.delta_bytes));text('target-size',size(M.target.bytes));text('reuse-size',size(M.summary.reused_bytes));text('saved',(100*(1-D.delta_bytes/M.target.bytes)).toFixed(1)+'% less transfer than the full target');text('member-count',M.changes.filter(r=>r.after!==null).length.toLocaleString()+' complete original members');for(const k of ['base','target']){text(k+'-name',M[k].filename);text(k+'-hash','SHA-256 '+M[k].sha256)}text('delta-name',D.delta_filename);text('delta-hash','SHA-256 '+D.delta_sha256);text('recipe-id','Delivery '+M.id);let page=0;const pageSize=75;function draw(){let q=$('filter').value.trim().toLowerCase(),status=$('status').value;let rows=M.changes.filter(r=>r.path.toLowerCase().includes(q)&&(status==='all'||status==='different'&&r.status!=='unchanged'||status===r.status));page=Math.max(0,Math.min(page,Math.ceil(rows.length/pageSize)-1));$('rows').replaceChildren();for(const r of rows.slice(page*pageSize,(page+1)*pageSize)){const tr=document.createElement('tr');for(const [i,v]of [r.status,r.path,size(r.before?.bytes),size(r.after?.bytes)].entries()){const td=document.createElement('td');td.textContent=v;if(i===1)td.className='path';tr.append(td)}$('rows').append(tr)}text('count',rows.length.toLocaleString()+' matching paths / '+M.changes.length.toLocaleString()+' total');text('page',rows.length?'Rows '+(page*pageSize+1)+'–'+Math.min((page+1)*pageSize,rows.length):'0 rows');$('empty').hidden=rows.length>0;$('prev').disabled=page===0;$('next').disabled=(page+1)*pageSize>=rows.length}for(const id of ['filter','status'])$(id).addEventListener(id==='filter'?'input':'change',()=>{page=0;draw()});$('clear').onclick=()=>{$('filter').value='';$('status').value='different';page=0;draw()};$('prev').onclick=()=>{page--;draw()};$('next').onclick=()=>{page++;draw()};function save(name,body,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('manifest').onclick=()=>save('archive-delta-recipe.json',JSON.stringify(M,null,2),'application/json');function csv(v){return'"'+String(v??'').replaceAll('"','""')+'"'}$('csv').onclick=()=>save('archive-file-changes.csv',[['status','path','before_bytes','after_bytes','before_sha256','after_sha256'],...M.changes.map(r=>[r.status,r.path,r.before?.bytes,r.after?.bytes,r.before?.sha256,r.after?.sha256])].map(r=>r.map(csv).join(',')).join('\r\n')+'\r\n','text/csv');$('instructions').onclick=()=>save('RECEIVE_INCREMENTAL_STUDY.txt','Base: '+M.base.filename+'\nSHA-256: '+M.base.sha256+'\nDelta: '+D.delta_filename+'\nSHA-256: '+D.delta_sha256+'\n\n'+$('command').textContent+'\n\nTarget SHA-256: '+M.target.sha256+'\nKeep the original base. Repeat the same command to resume; use a new receiving directory for an independent editable project.\n','text/plain');draw();
</script></html>'''
    return template.replace('COMMAND', html.escape(command)).replace('PAYLOAD', payload)
